const alreadyIncluded = new Set(entries.map(([, , imdbId]) => imdbId))
function appendExtras(type: CatalogItemType, extras: Array<[string, string, number, string]>): void {
  for (const [title, imdbId, year, genres] of extras) {
    if (alreadyIncluded.has(imdbId)) continue
    alreadyIncluded.add(imdbId)
    entries.push([type, title, imdbId, year, genres, `${title} é uma produção de ${genres.toLocaleLowerCase('pt-BR')} lançada em ${year}.`])
  }
}
appendExtras('movie', extraMovies)
appendExtras('series', extraSeries)
appendExtras('movie', moreMovies)
appendExtras('series', moreSeries)

export const localCatalog: CatalogItem[] = entries.map(([type, title, imdbId, year, genreText, description]) => {
  const genres = genreText.split(', ')
  const poster = `https://images.metahub.space/poster/medium/${imdbId}/img`
  return {
    id: `${type}:${imdbId}`, imdbId, title, originalTitle: title,
    caption: `${genres.join(' • ')} • ${year}`, poster, backdrop: poster, type,
    description, rating: undefined, releaseYear: year, genres, cast: [], relatedItems: [],
  }
})

export function getLocalItem(id: string | number, type?: CatalogItemType): CatalogItem | undefined {
  const value = String(id)
  return localCatalog.find((item) => (item.imdbId === value || item.id === value) && (!type || item.type === type))
}

export function getLocalPage(type: CatalogItemType, page = 1, pageSize = 10): CatalogPage {
  const items = localCatalog.filter((item) => item.type === type)
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize))
  const safePage = Math.max(1, Math.min(page, totalPages))
  return { items: items.slice((safePage - 1) * pageSize, safePage * pageSize), page: safePage, totalPages, totalResults: items.length }
}

export function searchLocalCatalog(filters: SearchFilters): CatalogPage {
  const query = filters.query.trim().toLocaleLowerCase('pt-BR')
  const matches = localCatalog.filter((item) =>
    (!filters.type || item.type === filters.type) &&
    (!filters.year || String(item.releaseYear) === filters.year) &&
    (!query || `${item.title} ${item.originalTitle} ${item.genres.join(' ')}`.toLocaleLowerCase('pt-BR').includes(query)),
  )
  const totalPages = Math.max(1, Math.ceil(matches.length / 10))
  const page = Math.max(1, Math.min(filters.page, totalPages))
  return { items: matches.slice((page - 1) * 10, page * 10), page, totalPages, totalResults: matches.length }
}
